// Validate and normalise incoming webhook payload
// Expected: { file_path, source, type }
const body = $input.item.json.body || $input.item.json;

if (!body.file_path) throw new Error('Missing required field: file_path');
if (!body.type)      throw new Error('Missing required field: type');

const filePath  = body.file_path;
const source    = body.source || 'workflow';
const mediaType = body.type;
const timestamp = Date.now();
const filename  = `${timestamp}_${filePath.split('/').pop() || 'asset'}`;

return [{
  json: {
    _filePath: filePath,
    _source:   source,
    _mediaType: mediaType,
    _timestamp: timestamp,
    _filename:  filename
  }
}];

// Read file from local disk for description
const fs   = require('fs');
const path = require('path');
const item = $input.item.json;

const mediaType = item._mediaType;

// For audio: skip vision, return placeholder
if (mediaType === 'audio') {
  return [{
    json: { ...item, _description: 'Audio asset generated by workflow.', _tags: 'audio,generated,workflow', _skipHaiku: true }
  }];
}

// Read file as base64 for Haiku
try {
  const buf = fs.readFileSync(item._filePath);
  return [{
    json: { ...item, _base64: buf.toString('base64'), _skipHaiku: false }
  }];
} catch (err) {
  // File not readable — use filename as description fallback
  return [{
    json: {
      ...item,
      _description: `Asset: ${path.basename(item._filePath)}`,
      _tags: `${mediaType},generated,workflow`,
      _skipHaiku: true
    }
  }];
}

