// Parse Haiku response; or pass through pre-set description for audio/unreadable
const item = $input.item.json;

let description = item._description || '';
let tags        = item._tags        || '';

if (!description && item.content) {
  const text     = item.content[0]?.text || '';
  const descMatch = text.match(/DESCRIPTION:\s*(.+?)(?=TAGS:|$)/s);
  const tagsMatch = text.match(/TAGS:\s*(.+)/s);
  description = descMatch ? descMatch[1].trim() : text.slice(0, 200);
  tags        = tagsMatch ? tagsMatch[1].trim() : '';
}

return [{
  json: {
    ...item,
    _description: description,
    _tags:        tags
  }
}];

// Append to /media-memory/index.jsonl
const fs   = require('fs');
const item = $input.item.json;

const entry = JSON.stringify({
  id:          item._filename,
  filename:    item._filename,
  type:        item._mediaType,
  timestamp:   item._timestamp,
  source:      item._source,
  description: item._description,
  tags:        item._tags ? item._tags.split(',').map(t => t.trim()) : [],
  path:        item._filePath
});

const indexPath = '/media-memory/index.jsonl';
try {
  fs.appendFileSync(indexPath, entry + '\n', 'utf8');
} catch (err) {
  console.error('Failed to append to index.jsonl:', err.message);
}

return [{ json: { record_id: item._filename, status: 'stored' } }];
